import java.util.*;
import java.util.function.*;

public class Lambdas {
    public static void main(String[] args) {
        List<String> names = new ArrayList<>(List.of("Zoe", "Al", "Bea", "Cy"));

        Comparator<String> byLength = (a, b) -> Integer.compare(a.length(), b.length());
        names.sort(byLength.thenComparing(Comparator.naturalOrder()));   // length, then text.
        System.out.println(names);                        // [Al, Cy, Bea, Zoe]

        names.sort(Comparator.comparing(String::length)); // method reference, same idea.

        Predicate<String> shortName = s -> s.length() <= 2;
        Function<String, String> shout = String::toUpperCase;
        int limit = 2;                                     // effectively final: captured.
        names.stream().filter(s -> s.length() <= limit).map(shout)
             .forEach(System.out::println);                // AL, CY
        System.out.println(shortName.test("Bea"));        // false
    }
}
